@layer components {
  .reactions {
    --btn-icon-size: 1.3em;
    --column-gap: 0.4ch;
    --reaction-border-color: var(--color-ink-lighter);
    --row-gap: 0;

    align-items: center;
    display: flex;
    flex-wrap: wrap;
    gap: var(--inline-space-half);
    inline-size: 100%;
    margin-block-start: var(--block-space-half);
    margin-inline: calc(var(--column-gap) / -1);
    z-index: 3;

    &:has([open]) {
      z-index: var(--z-popup);
    }

    &:not(:has(.reaction)) {
      inline-size: auto;

      .reactions__list {
        display: none;
      }

      .reactions__trigger {
        --btn-border-color: var(--color-ink-lightest);
        background-color: var(--color-ink-lightest);

        &:not(:hover) {
          opacity: 0.66;
        }
      }
    }
  }

  .reactions__trigger {
    --btn-size: var(--reaction-size);
    --btn-border-color: var(--reaction-border-color);

    img {
      block-size: 65%;
      inline-size: 65%;
    }
  }

  .reactions__list {
    display: inline-flex;
    flex-wrap: wrap;
    gap: var(--inline-space-half);

    &:not(:has(.reaction)) {
      display: none;
    }
  }

